"""Swap the letterhead/banner wide logo for a baked PNG (text can't break on any font). Safe to re-run."""
import base64, frappe
frappe.init(site="zanaschools-staging.zanaverse.com", sites_path="."); frappe.connect(); frappe.set_user("Administrator")
NAME = "zis-logo-wide-v2.png"
path = frappe.get_site_path("public", "files", NAME)
open(path, "wb").write(base64.b64decode(""))
url = "/files/" + NAME
if not frappe.db.exists("File", {"file_url": url}):
    frappe.get_doc({"doctype": "File", "file_name": NAME, "file_url": url, "is_private": 0}).insert(ignore_permissions=True)
lh = frappe.get_doc("Letter Head", "Zana International School")
lh.content = lh.content.replace("/files/zis-logo-wide.svg", url)
lh.save(ignore_permissions=True)
frappe.db.set_single_value("Website Settings", "banner_image", url)
frappe.db.commit(); frappe.clear_cache()
print("logo file :", url, len(open(path, "rb").read()), "bytes")
print("letterhead uses it:", url in lh.content)
frappe.destroy()
